    ["%d day(s) remaining"] = "%d일 남음",
    ["%d recorded spawn points"] = "기록된 생성 지점 %d개",
    ["%s (Rare)"] = "%s (희귀)",
    ["%s is under development."] = "%s은(는) 개발 중입니다.",
    ["**A boss with nothing to collect says so**, in one line."] = "**수집할 것이 없는 우두머리는 그렇게 표시합니다**, 한 줄로 간단히 보여 줍니다.",
    ["**Boss kills register in every dungeon.** When the game doesn't report a kill, the addon reads the instance's own objectives and picks it up within seconds."] = "**모든 던전에서 우두머리 처치가 기록됩니다.** 게임이 처치를 보고하지 않을 때는 애드온이 인스턴스 자체 목표를 읽어 몇 초 안에 처치를 감지합니다.",
    ["**Bosses you cannot reach no longer hold the count open.** Sinestra outside Heroic and Ra-den in Throne of Thunder now carry a lock."] = "**도달할 수 없는 우두머리가 완료 수를 막지 않습니다.** 영웅 난이도가 아닌 시네스트라와 천둥의 왕좌의 라덴에는 이제 자물쇠가 표시됩니다.",
    ["**Browsing another instance no longer highlights \"current difficulty\".** The white \"needed-now\" color only appears for the instance you are standing in."] = "**다른 인스턴스를 살펴볼 때 더 이상 “현재 난이도”가 강조되지 않습니다.** 흰색 “지금 필요” 색상은 현재 서 있는 인스턴스에만 나타납니다.",
    ["**Dungeons in the current Mythic+ season are marked.** A \"M+\" tag beside the name, and it follows the rotation on its own with no update needed. This serves as a heads up to avoid Mythic runs that are on seasonal rotation."] = "**현재 신화+ 시즌의 던전이 표시됩니다.** 이름 옆에 “M+” 태그가 붙고 업데이트 없이도 시즌 로테이션을 자동으로 따라갑니다. 시즌 로테이션에 포함된 던전을 신화 난이도로 돌지 않도록 미리 알려 줍니다.",
    ["**Dungeons!** Initially shipping with 20 dungeons which includes every Classic dungeon plus a couple from MoP. More dungeons will continue to be added! While the routes/guides are being developed for more dungeons, feel free to utilize the transmog browser for ALL dungeons, as well as pink plane navigation to every entrance."] = "**던전!** 처음에는 Classic의 모든 던전과 MoP의 일부를 포함해 20개 던전을 제공합니다. 앞으로 더 많은 던전이 계속 추가됩니다! 추가 던전의 경로와 가이드를 만드는 동안에도 모든 던전의 형상변환 브라우저와 각 입구로 향하는 분홍색 경로 안내를 사용할 수 있습니다.",
    ["**Every window closes the same way.** The Achievements, Transmog and Skips windows use the same styled close box as the main panel."] = "**모든 창이 같은 방식으로 닫힙니다.** 업적, 형상변환, 건너뛰기 창이 메인 패널과 같은 스타일의 닫기 상자를 사용합니다.",
    ["**Faction-only bosses are marked.** Uldaman's Lost Dwarves are Horde only, so on Alliance the row shows a lock and the boss count skips them."] = "**진영 전용 우두머리가 표시됩니다.** 울다만의 길 잃은 드워프는 호드 전용이므로 얼라이언스에서는 해당 줄에 자물쇠가 표시되고 우두머리 수에서도 제외됩니다.",
    ["**Looks that can no longer be collected are gone from the browser.** Dungeon Set 1 pieces with no boss drops, the Tier 0.5 summons, and season-only rows in modern dungeons. Anything still collectable elsewhere is still listed there."] = "**더 이상 수집할 수 없는 외형은 브라우저에서 제거되었습니다.** 우두머리 드롭이 없는 던전 세트 1 부위, 티어 0.5 소환, 현대 던전의 시즌 전용 줄이 포함됩니다. 다른 곳에서 아직 수집 가능한 항목은 계속 그곳에 표시됩니다.",
    ["**Looks that were missing are back.** Several pieces the Encounter Journal never listed are back, including End Time's Bindings of the End Times and Roogug's Swinesteel Girdle."] = "**누락됐던 외형이 돌아왔습니다.** 모험 안내서에 표시되지 않았던 여러 부위를 복원했으며, 시간의 끝의 Bindings of the End Times와 Roogug의 Swinesteel Girdle 등이 포함됩니다.",
    ["**Loot lists are tidier.** Normal and Heroic drops collapse to one row, trash groups by source, shared notes appear once, and token lines lead the list."] = "**전리품 목록이 더 깔끔해졌습니다.** 일반과 영웅 전리품은 한 줄로 합쳐지고, 일반 몬스터는 출처별로 묶이며, 공통 참고 사항은 한 번만 표시되고 토큰 줄이 목록 앞에 나옵니다.",
    ["**Map markers show more.** Rare spawns and certain treasures now show their locations on the map along with a mouseover hint to give a quick status on tracked appearances."] = "**지도 표시가 더 많은 정보를 보여 줍니다.** 희귀 몬스터와 일부 보물의 위치가 지도에 표시되며, 마우스를 올리면 추적 중인 외형의 상태를 빠르게 확인할 수 있습니다.",
    ["**Progress persists in dungeons with no lockout.** Normal dungeons keep no lockout, so the game gives an addon nothing to know whether the previous run is still there or if it reset. RetroRuns works it out anyway: log in, reload or walk back in and an active run comes back with every kill in place, while a reset instance starts you at step one on the spot."] = "**귀속이 없는 던전에서도 진행 상황이 유지됩니다.** 일반 던전은 귀속이 없기 때문에 게임은 이전 진행이 남아 있는지 초기화됐는지 애드온에 알려 주지 않습니다. RetroRuns는 그래도 이를 판별합니다. 로그인하거나 UI를 다시 불러오거나 다시 입장하면 활성 진행은 모든 처치 상태와 함께 복원되고, 초기화된 인스턴스는 즉시 첫 단계부터 시작합니다.",
    ["**Raid maps mark the NPCs worth knowing about.** Blackrock Foundry's skip-quest NPC and vendor, Icecrown Citadel's tier vendors, Blackwing Lair's alchemy workbenches and the like, each with a hover saying what it is for."] = "**공격대 지도에 알아둘 만한 NPC가 표시됩니다.** 검은바위 용광로의 건너뛰기 퀘스트 NPC와 상인, 얼음왕관 성채의 세트 상인, 검은날개 둥지의 연금술 작업대 등 유용한 위치가 표시되고, 마우스를 올리면 용도를 확인할 수 있습니다.",
    ["**Rare, trash and object drops are in the transmog browser.** Rares get a gold \"Rare:\" tag, trash drops get their own section, and Dungeon Set pieces show up on the bosses that drop them. Items that have been removed from the game or have become unobtainable are excluded."] = "**희귀 몬스터, 일반 몬스터, 오브젝트 전리품이 형상변환 브라우저에 표시됩니다.** 희귀 몬스터에는 금색 “희귀:” 태그가 붙고, 일반 몬스터 전리품은 별도 구역에 표시되며, 던전 세트 부위는 해당 부위를 드롭하는 우두머리에 표시됩니다. 게임에서 제거됐거나 더 이상 얻을 수 없는 아이템은 제외됩니다.",
    ["**RetroRuns has a button on the world map.** It sits in the icon column at the top-right corner alongside other addons' map buttons. Its menu has several map options to toggle, such as hiding POIs you've fully collected or disabling RetroRuns POIs altogether."] = "**RetroRuns가 세계 지도에 버튼을 추가합니다.** 오른쪽 위 아이콘 열에서 다른 애드온의 지도 버튼과 함께 표시됩니다. 메뉴에서 모두 수집한 관심 지점을 숨기거나 RetroRuns 관심 지점을 완전히 끄는 등 여러 지도 옵션을 전환할 수 있습니다.",
    ["**Search, everywhere.** The transmog browser, the main panel and the achievements window all have a new magnifying glass. Search by expansion, instance, boss, loot, POI, etc. Whatever you find, one click takes you right to it."] = "**어디서나 검색.** 형상변환 브라우저, 메인 패널, 업적 창에 모두 새로운 돋보기가 생겼습니다. 확장팩, 인스턴스, 우두머리, 전리품, 관심 지점 등으로 검색하세요. 무엇을 찾든 한 번 클릭하면 바로 그곳으로 이동합니다.",
    ["**Siege of Orgrimmar and newer raids have their lockout tooltip back.**"] = "**오그리마 공성전과 그 이후 공격대에 귀속 툴팁이 다시 표시됩니다.**",
    ["**Smaller fixes.** The Skips window updates on quest turn-in, a finished skip run in a dungeon reads right, the map button closes the map on a second click, loot toasts say \"Browse locked in combat\" instead of erroring, The MOTHERLODE!! travel plane knows both faction entrances, and zoning into a dungeon paints the panel right away."] = "**기타 수정.** 퀘스트를 완료하면 건너뛰기 창이 갱신되고, 던전에서 완료된 건너뛰기 진행이 올바르게 표시되며, 지도 버튼을 두 번째 클릭하면 지도가 닫힙니다. 전리품 알림은 오류 대신 “전투 중에는 탐색할 수 없습니다”라고 표시하고, 왕노다지 광산!! 이동 경로는 양 진영 입구를 모두 인식하며, 던전에 입장하면 패널이 즉시 갱신됩니다.",
    ["**The achievements window covers dungeons.** A Raids / Dungeons switch sits above the instance list, an instance with nothing to track says so, and a Report button in the footer allows users to flag a solo grade that has gone stale."] = "**업적 창이 던전도 지원합니다.** 인스턴스 목록 위에 공격대 / 던전 전환 버튼이 있으며, 추적할 내용이 없는 인스턴스는 이를 표시합니다. 하단의 신고 버튼으로 오래된 솔로 등급을 제보할 수도 있습니다.",
    ["**The idle footer counts your instances.** \"Instance Limit: 3/10 (42m)\" shows how many you've entered against the hourly cap and when the oldest slot frees. Only shows when outside of an instance."] = "**대기 중인 하단 표시줄이 인스턴스 횟수를 셉니다.** “인스턴스 제한: 3/10 (42m)”은 시간당 제한에 대해 몇 번 입장했는지와 가장 오래된 슬롯이 언제 비는지를 보여 줍니다. 인스턴스 밖에 있을 때만 표시됩니다.",
    ["**The list knows when Timewalking is running.** An hourglass marks the live Timewalking expansion and every instance that offers a run. The hourglass color indicates how much time remains on the event."] = "**목록이 시간여행 진행 여부를 압니다.** 모래시계가 현재 시간여행 확장팩과 이용 가능한 모든 인스턴스를 표시합니다. 모래시계 색으로 이벤트 종료까지 남은 시간을 알 수 있습니다.",
    ["**The menu dropdowns are rebuilt.** The Transmog, Achievements and Settings dropdowns use the game's current menu system, with a slimmer bar, a magenta arrow and no hover popups."] = "**메뉴 드롭다운을 새로 만들었습니다.** 형상변환, 업적, 설정 드롭다운이 게임의 현재 메뉴 시스템을 사용하며, 더 얇은 막대와 자홍색 화살표를 사용하고 마우스오버 팝업은 없습니다.",
    ["**The nav plane sits beside the raid's name**, instead of beside the difficulty pills."] = "**경로 안내 평면이 공격대 이름 옆에 표시됩니다**, 난이도 표시 옆이 아닙니다.",
    ["**The panel header is tidier.** Centered wordmark, a magenta underline that survives small UI scales, and \"Run complete!\" on the minimized bar. Text that previously said \"raid\" now says \"instance\"."] = "**패널 머리글이 더 깔끔해졌습니다.** 가운데 정렬된 로고, 작은 UI 배율에서도 유지되는 자홍색 밑줄, 그리고 최소화된 막대의 “진행 완료!” 표시가 추가되었습니다. 이전에 “공격대”라고 하던 문구는 이제 “인스턴스”라고 표시됩니다.",
    ["**The panel stays where you put it.** No more creeping up the screen after quitting minimized, and no more collapsing on reload."] = "**패널이 놓은 위치에 그대로 있습니다.** 최소화한 상태로 종료한 뒤 화면 위로 조금씩 이동하지 않으며, 다시 불러올 때 접히지도 않습니다.",
    ["**The transmog browser can open on All classes.** A \"Default Transmog Filter\" setting under General picks whether the browser opens on your class or on every class. The dropdown inside the browser still narrows it per visit."] = "**형상변환 브라우저를 모든 직업으로 열 수 있습니다.** 일반의 “기본 형상변환 필터” 설정으로 브라우저를 내 직업 또는 모든 직업으로 열지 선택합니다. 브라우저 내부 드롭다운으로는 방문할 때마다 다시 범위를 좁힐 수 있습니다.",
    ["**The transmog totals count each appearance once**, even when it drops from more than one place."] = "**형상변환 합계는 각 외형을 한 번만 계산합니다**, 여러 장소에서 드롭되더라도 마찬가지입니다.",
    ["**Tier upgrade chains read one way everywhere.** Firelands uses the same two-dot chain as every other raid, and the Icecrown Citadel legend explains the dots. Dragon Soul no longer lists every Raid Finder token under every boss."] = "**세트 업그레이드 단계가 어디서나 같은 방식으로 표시됩니다.** 불의 땅도 다른 공격대와 같은 두 점 연결 방식을 사용하며, 얼음왕관 성채 범례가 점의 의미를 설명합니다. 용의 영혼에서는 더 이상 모든 우두머리 아래에 공격대 찾기 토큰을 전부 나열하지 않습니다.",
    ["**Timewalking drops get their own \"TW\" pill.** Looks that only drop during Timewalking used to be hidden. Now they show with a TW pill."] = "**시간여행 전리품에는 전용 “TW” 표시가 붙습니다.** 시간여행 중에만 드롭되는 외형은 예전에는 숨겨졌지만, 이제 TW 표시와 함께 나타납니다.",
