    ["No instance loaded. Zone into a supported instance, or use:"] = "불러온 인스턴스가 없습니다. 지원되는 인스턴스에 입장하거나 다음을 사용하세요:",
    ["No matches."] = "일치하는 항목이 없습니다.",
