    ["We don't track kill / instance completion achievements unless they are tied to a Meta achievement."] = "처치 / 인스턴스 완료 업적은 메타 업적에 연결된 경우가 아니면 추적하지 않습니다.",
    ["World Map"] = "세계 지도",

    ["|cff9d9d9d(no instance data loaded)|r"] = "|cff9d9d9d(불러온 인스턴스 데이터 없음)|r",
    ["|cffff9333Routing data not yet captured for this instance.|r"] = "|cffff9333이 인스턴스의 경로 데이터는 아직 수집되지 않았습니다.|r",
    -- Sourced names (db2 / TDB verified)
    ["Aaurx"] = "아룩스",
    ["Amalgam of Souls"] = "영혼의 융합체",
    ["Ammunae"] = "아뮤내",
    ["Asaad"] = "아사드",
    ["Azzakel, Vanguard of the Legion"] = "군단의 선봉장 아자켈",
