    ["Vectus"] = "벡투스",

    ["**All MoP Dungeons are in.** Temple of the Jade Serpent, Mogu'shan Palace, Gate of the Setting Sun, Stormstout Brewery, Siege of Niuzao Temple, Shado-Pan Monastery and Scholomance join the two Scarlet halls, which makes 27 guided dungeons so far."] = "**MoP 던전이 모두 추가되었습니다.** 옥룡사, 모구샨 궁전, 석양문, 스톰스타우트 양조장, 니우짜오 사원 공성전, 음영파 수도원, 스칼로맨스가 두 붉은십자군 전당과 함께 지원되어, 현재 안내 던전은 총 27개입니다.",
    ["**Deadmines lists its six bosses.** Seven bosses from the pre-Cataclysm Deadmines that only appear in the Classic Timewalking event were showing in the list and the browser."] = "**죽음의 폐광은 6명의 우두머리만 표시합니다.** 대격변 이전 죽음의 폐광에서 Classic 시간여행 이벤트에만 등장하는 7명의 우두머리가 목록과 브라우저에 표시되고 있었습니다.",
    ["**Dungeon rows on the list line up with raid rows**: the plane icons share one column across both tabs."] = "**목록의 던전 행이 공격대 행과 정렬됩니다**: 두 탭의 비행기 아이콘이 같은 열을 사용합니다.",
    ["**Every expansion has its own custom art behind the main panel.** Open an expansion on the list, or load one of its instances, and a faded picture sits behind the content."] = "**각 확장팩마다 메인 패널 뒤에 전용 배경 그림이 표시됩니다.** 목록에서 확장팩을 열거나 해당 인스턴스에 들어가면 콘텐츠 뒤에 흐리게 처리된 그림이 나타납니다.",
    ["**Legacy of Scholomance is in the transmog browser.** The original Scholomance's appearances are listed under every Scholomance boss, with a note on how the attunement starts. The rare who drops the toy that starts it, Doctor Theolen Krastinov, is marked on the map."] = "**스칼로맨스의 유산이 형상변환 브라우저에 추가되었습니다.** 옛 스칼로맨스의 외형이 모든 스칼로맨스 우두머리 아래에 표시되며, 해금을 시작하는 방법도 안내됩니다. 시작용 장난감을 드롭하는 희귀 몬스터 Doctor Theolen Krastinov도 지도에 표시됩니다.",
    ["**Mogu'shan Palace's entrance waypoint** pointed at the old Vale of Eternal Blossoms map; it now lands on the current one."] = "**모구샨 궁전 입구 경유지**가 영원꽃 골짜기의 옛 지도 위치를 가리키고 있었습니다. 이제 현재 지도 위치로 안내합니다.",
    ["**One gray on the main panel.** Several different tints of gray were being used in various places on the main panel. Now they match."] = "**메인 패널의 회색을 하나로 통일했습니다.** 메인 패널 곳곳에서 서로 다른 회색 톤을 사용하고 있었습니다. 이제 모두 동일합니다.",
    ["**Polyformic Acid Science.** This achievement now shows on each of its six bosses across the Mists dungeons, with a solo grade."] = "**다형성 산성 과학.** 이제 이 업적이 Mists 던전의 관련 우두머리 6명 모두에 표시되며, 솔로 등급도 함께 표시됩니다.",
    ["**RetroRuns stays deactivated on M+ Dungeons.** When zoning into Heroic or Mythic difficulty on a seasonal M+ dungeon, the addon stays down. The minimap button or /rr still opens it by hand."] = "**RetroRuns는 M+ 던전에서 계속 비활성화됩니다.** 시즌 M+ 던전을 영웅 또는 신화 난이도로 입장하면 애드온이 열리지 않습니다. 미니맵 버튼이나 /rr로는 여전히 직접 열 수 있습니다.",
    ["**Scholomance, Deadmines and Shadowfang Keep show one row per item with a Normal and a Heroic pill.** The Heroic version of each drop was listed as a second row with no pills."] = "**스칼로맨스, 죽음의 폐광, 그림자송곳니 성채는 아이템당 한 줄에 일반 및 영웅 표시를 함께 보여 줍니다.** 각 드롭의 영웅 버전이 표시 없이 별도의 두 번째 줄로 나열되고 있었습니다.",
    ["**The addon download is a third smaller.** Media art moved to the game's native compressed format."] = "**애드온 다운로드 용량이 3분의 1 줄었습니다.** 미디어 그림을 게임의 기본 압축 형식으로 옮겼습니다.",
    ["**The instance-limit counter counts difficulty changes.** Switching a dungeon between Normal, Heroic and Mythic spawns a new instance each time, and the counter now reflects that."] = "**인스턴스 제한 카운터가 난이도 변경도 계산합니다.** 던전을 일반, 영웅, 신화 난이도 사이에서 변경할 때마다 새 인스턴스가 생성되며, 이제 카운터에도 반영됩니다.",
    ["**The Timewalking and Mythic+ tags on the instance list are text now**, sitting after the instance name on both tabs. They used to draw inconsistently from one row to the next."] = "**인스턴스 목록의 시간여행 및 신화+ 태그가 이제 텍스트로 표시됩니다**, 두 탭 모두 인스턴스 이름 뒤에 배치됩니다. 이전에는 행마다 표시 방식이 일정하지 않았습니다.",
    ["Challenge Gong"] = "도전의 징",
    ["Corrupted Scroll"] = "타락한 두루마리",
    ["Hardened Resin"] = "굳은 수지",
    ["Hoplings"] = "깡충이",
    ["Iron Gate"] = "철문",
    ["Seasonal M+ Dungeon detected. Routing is disabled for Heroic and Mythic difficulties."] = "시즌 M+ 던전이 감지되었습니다. 영웅 및 신화 난이도에서는 경로 안내가 비활성화됩니다.",
    ["Signal Flame"] = "신호 불꽃",
    ["Trial of Kings"] = "왕의 시험",

