    ["Ahead to Shriekwing"] = "앞쪽 절규날개",
    ["Ahead to Sinestra"] = "앞쪽 시네스트라",
    ["Ahead to Sivara"] = "앞쪽 시바라",
    ["Ahead to Stone Guard"] = "앞쪽 바위 수호자",
    ["Ahead to Taloc"] = "앞쪽 탈록",
    ["Ahead to Tel'arn"] = "앞쪽 텔아른",
    ["Ahead to Terros"] = "앞쪽 테로스",
    ["Ahead to Thalnos"] = "앞쪽 Thalnos",
    ["Ahead to The Jailer"] = "앞쪽 간수",
    ["Ahead to Thok"] = "앞쪽 토크",
    ["Ahead to Tortos"] = "앞쪽 토르토스",
    ["Ahead to Varimathras"] = "앞쪽 바리마트라스",
    ["Al'Akir also drops {item}, an omnitoken that allows you to purchase any Tier 11 set piece of matching quality. Not tracked here."] = "Al'Akir는 {item}도 드랍합니다. 같은 품질의 11티어 세트 부위를 아무거나 구매할 수 있는 만능 토큰입니다. 여기서는 추적하지 않습니다.",
    ["Alchemy Lab"] = "연금술 연구소",
    ["Alchemy Workbench"] = "연금술 작업대",
    ["Amnennar spawns here"] = "여기서 Amnennar 등장",
    ["Approach ^Tindral^ to trigger the encounter."] = "^Tindral^에게 접근해 전투를 시작하세요.",
    ["Approach Felmyst to pull"] = "Felmyst에게 접근해 전투 시작",
    ["Approach the boss, and kill the trash to engage ^Rashok^."] = "우두머리에게 접근해 일반 몬스터를 처치하면 ^Rashok^과 전투할 수 있습니다.",
    ["Approach the bridge and take a left. Follow the path to ^Oregorger^. Clear trash to spawn the boss."] = "다리에 접근해 왼쪽으로 가세요. 길을 따라 ^Oregorger^에게 가세요. 일반 몬스터를 처치해 우두머리를 생성하세요.",
    ["Approach Tindral"] = "틴드랄에게 접근",
    ["Armaments"] = "무장",
    ["Armory"] = "무기고",
    ["As you cross the bridge, dodge fire so you don't get thrown over the edge. At the end of the bridge, you will find ^Smolderon^."] = "다리를 건너면서 불길을 피해 가장자리 밖으로 날아가지 않도록 하세요. 다리 끝에서 ^Smolderon^을 찾을 수 있습니다.",
    ["As you work your way up, stay to the right and follow the path into a room where you will find ^C'Thun^!"] = "올라갈 때 오른쪽을 따라가며 방으로 들어가면 ^C'Thun^을 찾을 수 있습니다!",
    ["Aspirant Forudir"] = "Aspirant Forudir",
    ["Aspirant Naradiel"] = "Aspirant Naradiel",
    ["Assembled from 30 Fragments of Val'anyr, which drop across Ulduar; the hammer is forged during the Yogg-Saron encounter."] = "울두아르 전역에서 드랍되는 발아니르의 조각 30개로 조립하며, 요그사론 전투 중 망치를 완성합니다.",
    ["At bottom go west to Royalty"] = "아래에서 서쪽 Royalty로",
    ["At end of path, left to Zigris"] = "길 끝에서 왼쪽, Zigris",
    ["At the bottom of the elevator, go north to reach the ^Signal Flame^. Click it to trigger a cutscene."] = "승강기 아래에서 북쪽으로 가 ^Signal Flame^에 도착하세요. 클릭하면 영상이 시작됩니다.",
    ["At the bottom of the stairs, talk to Grand Artificer Romuul for several teleport options."] = "계단 아래에서 대기술병 로뮬에게 말하면 여러 순간이동 선택지를 이용할 수 있습니다.",
    ["At the top of the ramp, continue ahead until you reach ^Netherspite^."] = "경사로 꼭대기에서 계속 앞으로 가 ^Netherspite^에게 가세요.",
    ["At the top of the stairs, clear the elite trash on the platform to spawn ^Garalon^."] = "계단 위에서 단상의 정예 일반 몬스터를 처치해 ^Garalon^을 생성하세요.",
    ["At the top of the stairs, walk through a door and click on the ^Displacement Pad^. After landing, engage ^Lei Shen^."] = "계단 위에서 문을 지나 ^Displacement Pad^를 클릭하세요. 착지한 뒤 ^Lei Shen^과 전투하세요.",
    ["Avoid blue circles"] = "파란 원 피하기",
    ["Avoid Sticky Webbing on the ground. The boss will attempt to pull you off the edge with Gossamer Burst. Easiest way to avoid this is to step on a Sticky Webbing before he finishes the cast. When he ascends, follow him up and finish the kill."] = "바닥의 끈끈한 거미줄을 피하세요. 우두머리가 비단 폭발로 가장자리 밖으로 끌어내려고 합니다. 시전이 끝나기 전에 끈끈한 거미줄을 밟는 것이 가장 쉬운 대처법입니다. 우두머리가 올라가면 따라 올라가 처치하세요.",
    ["Awarded together at the end of a long Rogue chain that begins by pickpocketing Hagara the Stormbinder."] = "폭풍결속자 하가라에게 소매치기하는 것으로 시작하는 긴 도적 연계 퀘스트 끝에서 두 아이템을 함께 받습니다.",
    ["Back down stairs"] = "계단 아래로 되돌아가기",
    ["Back in ^Hellfire Antechamber^, follow the path to reach ^Gorefiend^. Kill the trash to start the encounter."] = "^Hellfire Antechamber^로 돌아온 뒤, 길을 따라 ^Gorefiend^에게 가세요. 일반 몬스터를 처치해 전투를 시작하세요.",
    ["Back in ^The Primal Convergence^, follow the newly-opened path to ^Kurog Grimtotem^."] = "^The Primal Convergence^로 돌아온 뒤, 새로 열린 길을 따라 ^Kurog Grimtotem^에게 가세요.",
    ["Back in ^Underhold Nexus^, go straight ahead to another door marked on the map."] = "^Underhold Nexus^로 돌아온 뒤, 정면의 지도에 표시된 다른 문으로 가세요.",
    ["Back in the ^Ring of Containment^, head north to the map exit labeled ^Plague Vault^."] = "^Ring of Containment^로 돌아온 뒤, 북쪽의 지도 출구 ^Plague Vault^로 가세요.",
    ["Back in the ^Underhold Nexus^, take the southern (final) door marked on the map."] = "^Underhold Nexus^로 돌아온 뒤, 지도에 표시된 남쪽의 마지막 문으로 가세요.",
    ["Back in the library, continue up the ramps and open the ^Private Library Door^ to reach ^Shade of Aran^. Note: Killing this boss unlocks a teleport from the entrance NPC to this room, if you need to leave/logout and come back later."] = "도서관으로 돌아오면 경사로를 계속 올라 ^Private Library Door^를 열고 ^Shade of Aran^에게 가세요. 참고: 이 우두머리를 처치하면 입구 NPC에서 이 방으로 순간이동할 수 있어, 나갔다가/로그아웃했다가 나중에 돌아오기 편합니다.",
    ["Back in the main concourse, take the northern exit and go up some stairs."] = "주 회랑으로 돌아오면 북쪽 출구로 나가 계단을 올라가세요.",
    ["Back in the main lobby, take the northeast exit towards ^Iron Assembly^."] = "중앙 로비로 돌아온 뒤, 북동쪽 출구로 나가 ^Iron Assembly^로 가세요.",
    ["Back on Antorus, proceed forward and click on one of the ^Lightforged Warframes^ to be flown to the next area."] = "안토러스에 돌아온 뒤, 앞으로 가 ^Lightforged Warframes^ 중 하나를 클릭해 다음 지역으로 날아가세요.",
    ["Back on the main level of ^Astromancer's Rise^, take the northeast exit from the building towards the map exit labeled ^Shal'dorei Terrace^."] = "^Astromancer's Rise^의 중앙 층으로 돌아온 뒤, 건물 북동쪽 출구로 나가 지도에 ^Shal'dorei Terrace^로 표시된 출구로 가세요.",
    ["Back outside, follow the path to the east until you reach ^Taran Zhu^."] = "다시 야외로 나오면 동쪽 길을 따라 ^Taran Zhu^까지 가세요.",
    ["Back through pipe"] = "관을 통해 되돌아가기",
    ["Back to Core hub"] = "핵심부 중심지로 되돌아가기",
    ["Back to courtyard"] = "안뜰로 되돌아가기",
    ["Back to Nighthold"] = "밤의 요새로 되돌아가기",
    ["Back to Underhold Nexus"] = "지하요새 연결부로 되돌아가기",
    ["Backtrack ahead to Razorscale"] = "되돌아가 앞쪽 칼날비늘",
    ["Backtrack and take ramp down"] = "되돌아가 경사로 아래로",
    ["Backtrack east, Rotgrip in water"] = "동쪽으로 되돌아가면 물속 Rotgrip",
    ["Backtrack path to Sartura"] = "Sartura까지 되돌아가기",
    ["Backtrack south then left to Emalon"] = "남쪽으로 되돌아간 뒤 왼쪽 에말론",
    ["Backtrack then left to Faerlina"] = "되돌아간 뒤 왼쪽 팰리나",
    ["Backtrack then left to Toravon"] = "되돌아간 뒤 왼쪽 토라본",
    ["Backtrack then north to Council"] = "되돌아간 뒤 북쪽 의회",
    ["Backtrack then upstairs"] = "되돌아간 뒤 위층으로",
    ["Backtrack through bookcase"] = "책장을 통해 되돌아가기",
    ["Backtrack to Chief Ukorz"] = "Chief Ukorz까지 되돌아가기",
    ["Backtrack to east stairs"] = "동쪽 계단으로 되돌아가기",
    ["Backtrack to Halls of Chosen"] = "선택받은 자의 전당으로 되돌아가기",
    ["Backtrack to Halls of the Faithful"] = "신실한 자의 전당으로 되돌아가기",
    ["Backtrack to main concourse"] = "주 회랑으로 되돌아가기",
    ["Backtrack to Ring of Containment"] = "봉쇄의 고리로 되돌아가기",
    ["backtrack to stairs for Kologarn"] = "계단으로 되돌아가 콜로간",
    ["Backtrack to The Primal Convergence"] = "원시의 합일점으로 되돌아가기",
    ["Backtrack to The Vault Approach"] = "금고 진입로로 되돌아가기",
    ["Backtrack towards Feast of Arrogance"] = "오만의 연회 쪽으로 되돌아가기",
    ["Backtrack towards Kel'Thuzad"] = "켈투자드 쪽으로 되돌아가기",
    ["Backtrack up to Majordomo"] = "Majordomo까지 위로 되돌아가기",
    ["Backtrack"] = "되돌아가기",
    ["Baron Geddon patrolling northeast"] = "Baron Geddon 북동쪽 순찰",
    ["Beacon to Burning Throne"] = "신호기로 불타는 왕좌",
    ["Beacon to The Exhaust"] = "신호기로 배기구",
    ["Behind the bookshelf, proceed down the ramp until you reach ^Terestian Illhoof^."] = "책장 뒤에서 경사로를 내려가 ^Terestian Illhoof^에게 가세요.",
    ["Bell"] = "종",
    ["Blackhand also drops {tokens}, which are omnitokens that you redeem for any Tier 17 set piece of matching quality. Not tracked here."] = "Blackhand는 {tokens}도 드랍합니다. 같은 품질의 17티어 세트 부위를 아무거나 교환할 수 있는 만능 토큰입니다. 여기서는 추적하지 않습니다.",
    ["Boots"] = "장화",
    ["Bosses must die around the same time. When you get polymorphed, run over green circles then press the button on your action bar to return to normal."] = "우두머리들을 비슷한 시점에 처치해야 합니다. 변이되면 초록색 원을 밟고 행동 단축바의 단추를 눌러 원래 모습으로 돌아오세요.",
    ["Bridge to Smolderon"] = "다리 건너 스몰데론",
    ["Bridge to Teleporter"] = "다리 건너 순간이동기",
    ["Bring boss health to 0 and it will trigger a new phase. Run to the boss, and an extra action button will appear. Use this button to enter the phylactery. Inside, kill the 1 enemy and you will appear back outside to kill the boss one more time."] = "우두머리의 생명력을 0으로 만들면 새 단계가 시작됩니다. 우두머리에게 달려가면 추가 행동 단추가 나타납니다. 단추를 눌러 성물함 안으로 들어가세요. 안의 적 1마리를 처치하면 밖으로 돌아오며, 우두머리를 한 번 더 처치하면 됩니다.",
    ["Bring them down slowly. If any of them die before the final phase, the fight can bug/reset. Once all 4 are active, cleave them down."] = "천천히 생명력을 낮추세요. 마지막 단계 전에 하나라도 죽으면 전투가 버그에 걸리거나 초기화될 수 있습니다. 4명이 모두 활성화되면 광역으로 처치하세요.",
    ["Buy base items and redeem tier tokens at:"] = "기본 아이템 구매 및 세트 토큰 교환:",
    ["Bypass Tribute Pile and go South"] = "Tribute Pile 우회 후 남쪽",
    ["Bypass Valithria on the outer edge"] = "바깥쪽 가장자리로 Valithria 우회",
    ["Cache of the Legion"] = "군단 저장고",
    ["Caer Darrow"] = "카엘 다로우",
    ["Cannot skip from here -- keep going until the route reaches the next boss."] = "여기서는 건너뛸 수 없습니다 -- 경로가 다음 우두머리에 도달할 때까지 계속 진행하세요.",
    ["Caster Weapons"] = "주문 시전자 무기",
    ["Cathedral"] = "대성당",
    ["Channel Formation Seed"] = "형성의 씨앗 정신집중",
    ["Channel Seed to Create Bridge"] = "씨앗에 정신집중해 다리 생성",
    ["Chest"] = "가슴",
    ["Choose any dialog options to start the fight; doesn't matter. To beat this encounter, visit all 4 rooms one at a time (by chain or by lever, depending on order). Inside each room, click boxes and defeat enemies to fill the meter, then pull the room's lever. After you pull the 4th lever, the fight is over. You must beat the timer!"] = "아무 대화 선택지나 골라 전투를 시작해도 됩니다. 이 전투를 끝내려면 방 4개를 한 곳씩 방문하세요(순서에 따라 사슬 또는 레버 이용). 각 방에서 상자를 클릭하고 적을 처치해 막대를 채운 다음, 방의 레버를 당기세요. 네 번째 레버를 당기면 전투가 끝납니다. 제한 시간 안에 완료해야 합니다!",
    ["Clear building"] = "건물 정리",
