    ["Click Teleportation Pad"] = "순간이동 발판 클릭",
    ["Click Teleporter"] = "순간이동기 클릭",
    ["Click the ^Disconcerting Bookshelf^ to open a secret passage."] = "^Disconcerting Bookshelf^를 클릭해 비밀 통로를 여세요.",
    ["Click the ^Downward Draft^ to be flown to the platform and engage ^Dathea, Ascended^."] = "^Downward Draft^를 클릭해 단상으로 날아가 ^Dathea, Ascended^와 전투하세요.",
    ["Click the ^Hammer of Khaz'goroth^ in the middle of this room after killing ^Demonic Inquisition^."] = "이 방 중앙의 ^Hammer of Khaz'goroth^는 ^Demonic Inquisition^을 처치한 뒤 클릭하세요.",
    ["Click the ^Tears of Elune^ in the middle of the room after killing ^The Desolate Host^."] = "방 중앙의 ^Tears of Elune^는 ^The Desolate Host^를 처치한 뒤 클릭하세요.",
    ["Click the ^Tidestone of Golganneth^ after killing ^Mistress Sassz'ine^."] = "^Tidestone of Golganneth^는 ^Mistress Sassz'ine^을 처치한 뒤 클릭하세요.",
    ["Click the nearby portal"] = "근처 차원문 클릭",
    ["Click the portal near The Frozen Throne to be teleported near the entrance"] = "얼어붙은 왕좌 근처 차원문을 클릭하여 입구 근처로 순간이동하세요",
    ["Click the portal to ^Wellspring Atrium^ to be teleported to the entrance."] = "^Wellspring Atrium^으로 가는 차원문을 클릭하여 입구로 순간이동하세요.",
    ["Click Tidestone"] = "해일석 클릭",
    ["Click Titan Console then Jump In"] = "티탄 제어 장치 클릭 후 뛰어들기",
    ["Click Titan Console"] = "티탄 제어 장치 클릭",
    ["Click Urn"] = "항아리 클릭",
    ["Click Valeera"] = "발리라 클릭",
    ["Click Valve then Professor"] = "밸브 클릭 후 교수",
    ["Click Valve then Rotface"] = "밸브 클릭 후 썩은얼굴",
    ["Click Valve"] = "밸브 클릭",
    ["Cloaks"] = "망토",
    ["Clockwise to Lord Roccor"] = "시계 방향으로 Lord Roccor",
    ["Conquest sold for gold/silver"] = "Conquest 골드/실버 판매",
    ["Console then bridge to Vashj"] = "콘솔 후 다리 건너 Vashj",
    ["Continue ahead in ^The Forgotten Pool^ until you reach ^Guardian of the Deep^."] = "^The Forgotten Pool^ 안에서 계속 앞으로 가 ^Guardian of the Deep^에게 가세요.",
    ["Continue ahead into the main courtyard to find ^Spellblade Aluriel^."] = "중앙 안뜰로 계속 가 ^Spellblade Aluriel^을 찾으세요.",
    ["Continue ahead to clear the trash and engage ^King Rastakhan^."] = "계속 앞으로 가 일반 몬스터를 처치하고 ^King Rastakhan^과 전투하세요.",
    ["Continue along the path until you reach a room with Ethereal enemies, and take the ramp up."] = "길을 따라가 에테리얼 적이 있는 방에 도착한 뒤 경사로를 올라가세요.",
    ["Continue backtracking through this room."] = "이 방을 계속 되돌아가세요.",
    ["Continue backtracking to main concourse. When you reach it, cut through the platform and take the northeast path out of this room."] = "계속 되돌아가 주 회랑으로 가세요. 도착하면 플랫폼을 가로질러 이 방의 북동쪽 길로 나가세요.",
    ["Continue climbing"] = "계속 올라가기",
    ["Continue climbing."] = "계속 올라가세요.",
    ["Continue down spiral"] = "나선 통로 아래로 계속",
    ["Continue down the path and clear the trash to spawn ^The Amalgamation Chamber^."] = "길을 계속 내려가 일반 몬스터를 처치해 ^The Amalgamation Chamber^를 생성하세요.",
    ["Continue down the stairs until you reach the room with ^Archaedas^. Activate the ^Altar of Archaedas^ to begin the fight."] = "계단을 계속 내려가 ^Archaedas^가 있는 방에 도착하세요. ^Altar of Archaedas^를 활성화하면 전투가 시작됩니다.",
    ["Continue down the stairs, and follow the linear path to the south side of the map. Jump down to engage ^Gekkan^."] = "계단을 내려가 지도 남쪽까지 이어지는 직선 길을 따라가세요. 아래로 뛰어내려 ^Gekkan^과 전투를 시작하세요.",
    ["Continue down the stairs, following the path until you reach ^Sisters of the Moon^."] = "계단을 계속 내려가 길을 따라 ^Sisters of the Moon^에게 가세요.",
    ["Continue following the linear path into the next room."] = "일직선 길을 계속 따라 다음 방으로 가세요.",
    ["Continue following the path ahead to reach ^Sennarth^."] = "앞쪽 길을 계속 따라 ^Sennarth^에게 가세요.",
    ["Continue following the path ahead to reach ^Terros^."] = "앞쪽 길을 계속 따라 ^Terros^에게 가세요.",
    ["Continue following the path through the waves of ^Hoplings^ until you reach ^Hoptallus^. Clear the trash to spawn the boss."] = "^Hoplings^의 웨이브를 지나 길을 계속 따라 ^Hoptallus^에게 가세요. 일반 몬스터를 처치하면 우두머리가 등장합니다.",
    ["Continue following the path to arrive back at the ^The Primal Bulwark^."] = "길을 계속 따라 ^The Primal Bulwark^로 돌아가세요.",
    ["Continue following the path to engage ^Fetid Devourer^."] = "길을 계속 따라 ^Fetid Devourer^와 전투하세요.",
    ["Continue following the path to reach ^Vectis^."] = "길을 계속 따라 ^Vectis^에게 가세요.",
    ["Continue following the path to reach ^Zek'voz, Herald of N'Zoth^. Clear trash to start the encounter."] = "길을 계속 따라 ^Zek'voz, Herald of N'Zoth^에게 가세요. 일반 몬스터를 처치해 전투를 시작하세요.",
    ["Continue forward to ^The Jailer^'s platform and end this."] = "계속 앞으로 가 ^The Jailer^의 단상에서 끝내세요.",
    ["Continue north through the ^Opera Hall Balcony^ and climb the ramp at the end."] = "^Opera Hall Balcony^를 지나 북쪽으로 계속 가고 끝의 경사로를 올라가세요.",
    ["Continue south past the final boss to reach the exit"] = "마지막 우두머리를 지나 남쪽으로 계속 가면 출구",
    ["Continue south to the elevator and take it down."] = "남쪽 엘리베이터까지 계속 가서 내려가세요.",
    ["Continue south until the path ends, and take a left to follow the path east until you reach ^Quartermaster Zigris^ walking around."] = "길이 끝날 때까지 남쪽으로 가고 왼쪽으로 돌아 동쪽 길을 따라 순찰 중인 ^Quartermaster Zigris^를 찾으세요.",
    ["Continue straight ahead on the southern path and you will run right into ^Thruk^."] = "남쪽 길을 바로 앞으로 가면 ^Thruk^을 만나게 됩니다.",
    ["Continue straight ahead to engage ^Conclave of the Chosen^."] = "직진해 ^Conclave of the Chosen^과 전투하세요.",
    ["Continue to Blackhand"] = "블랙핸드까지 계속",
    ["Continue to Gruul"] = "Gruul 쪽으로 계속",
    ["Continue up and around the stairwell until you reach ^Tichondrius^."] = "계단을 계속 올라 돌아가며 ^Tichondrius^에게 가세요.",
    ["Continue up path to exit right"] = "길 따라 올라가 오른쪽 출구",
    ["Continue up the ramp and clear the ogres. Use ^Omokk's Head^ while standing over ^Urok's Tribute Pile^ to summon ^Urok Doomhowl^. You can {skip} this boss if you want."] = "경사로를 올라 오우거를 정리하세요. ^Omokk's Head^를 사용하되 ^Urok's Tribute Pile^ 위에 서 있으면 ^Urok Doomhowl^이 소환됩니다. 원하면 이 우두머리를 {skip}할 수 있습니다.",
    ["Continue up the ramp and keep to the left, bypassing ^Urok's Tribute Pile^. Follow the ramp as it turns sharply back to the south."] = "경사로를 올라 왼쪽을 유지하며 ^Urok's Tribute Pile^을 우회하세요. 경사로가 급하게 남쪽으로 되돌아갈 때 그대로 따라가세요.",
    ["Continue up the ramp/stairs"] = "경사로/계단 계속 올라가기",
    ["Continue up the spiral stairwell."] = "나선 계단을 계속 올라가세요.",
    ["Continue up the stairs into ^The Grand Ballroom^. Take a left into ^The Banquet Hall^ and find ^Moroes^ up on a small platform."] = "계단을 계속 올라 ^The Grand Ballroom^으로 들어가세요. ^The Banquet Hall^ 쪽으로 왼쪽으로 가서 작은 플랫폼 위의 ^Moroes^를 찾으세요.",
    ["Continue up the stairs"] = "계단 계속 올라가기",
    ["Continue up the stairs. When you reach the top, follow the path to ^Mother Shahraz^."] = "계단을 계속 올라가세요. 꼭대기에서 길을 따라 ^Mother Shahraz^에게 가세요.",
    ["Continue working your way towards the central hub. When you get there, take the first path on the left and take the portal to ^Grizzly Hills^."] = "중앙 거점으로 계속 가세요. 도착하면 첫 번째 왼쪽 길로 들어가 ^Grizzly Hills^ 차원문을 이용하세요.",
    ["Continue working your way up the ramp and stairs."] = "경사로와 계단을 계속 올라가세요.",
    ["Crafted from the Bindings of the Windseeker. Garr and Baron Geddon each drop one half."] = "바람추적자의 족쇄로 제작합니다. 가르와 남작 게돈이 각각 절반씩 드랍합니다.",
    ["Crafted from the Eye of Sulfuras, a rare drop from Ragnaros."] = "라그나로스의 희귀 드랍인 설퍼라스의 눈으로 제작합니다.",
    ["Cross Bridge Ahead"] = "앞쪽 다리 건너기",
    ["Cross bridge, downstairs to Inner Sanctum"] = "다리 건너 아래층 내부 성소",
    ["Cross lava bridge"] = "용암 다리 건너기",
    ["Cross Lava to Neltharion's Sanctum"] = "용암 건너 넬타리온의 성소",
    ["Cross the bridge behind ^Anduin^ to the teleporter. Select ^Proceed^."] = "^Anduin^ 뒤의 다리를 건너 순간이동기로 가세요. ^Proceed^를 선택하세요.",
    ["Cross the room and take the southern exit."] = "방을 가로질러 남쪽 출구로 나가세요.",
    ["Cross to Maiden"] = "건너편 여신에게",
    ["Crusader Grimtong"] = "Crusader Grimtong",
    ["Crusader Halford"] = "Crusader Halford",
    ["Deactivate first shield generator"] = "첫 번째 보호막 생성기 비활성화",
    ["Death by lava near Slagmaw"] = "Slagmaw 근처 용암에서 사망",
    ["Destroy Bells"] = "종 파괴",
    ["Destroy Cannons"] = "대포 파괴",
    ["Dialog then Anduin"] = "대화 후 안두인",
    ["Dialog then Portal"] = "대화 후 차원문",
    ["Dialog then Raszageth"] = "대화 후 라자게스",
    ["Dialog then Shriekwing"] = "대화 후 절규날개",
    ["Dialog then Sludgefist"] = "대화 후 진흙주먹",
    ["Dialog then Sylvanas"] = "대화 후 실바나스",
    ["Dialog then Titan Console"] = "대화 후 티탄 제어 장치",
    ["Displacement Pad"] = "전이 발판",
    ["Do not attack ^Razorgore^ directly or you will wipe. To start the encounter properly, kill the adds on the opposite platform. Immediately click the ^Orb of Domination^ to mind control the boss. As quickly as you can, destroy all eggs in the room. You can do this by walking to each one and pressing the action button for ^Destroy Egg^. After you've killed the last egg, the mind control will end and you can kill ^Razorgore^. If you run out of time, kill adds and click the orb again to finish off the remaining eggs."] = "^Razorgore^을 직접 공격하면 전멸합니다. 전투를 제대로 시작하려면 반대쪽 플랫폼의 추가 몬스터를 처치하세요. 즉시 ^Orb of Domination^을 클릭해 우두머리를 정신 지배하세요. 방 안의 모든 알을 최대한 빨리 파괴하세요. 각 알로 이동해 ^Destroy Egg^ 행동 버튼을 누르세요. 마지막 알을 파괴하면 정신 지배가 끝나고 ^Razorgore^을 처치할 수 있습니다. 시간이 부족하면 추가 몬스터를 처치하고 보주를 다시 클릭해 남은 알을 처리하세요.",
    ["Door"] = "문",
    ["Down cliffside then west to Princess"] = "절벽 아래, 서쪽 Princess",
    ["Down hallway, left to Halycon"] = "복도 아래, 왼쪽 Halycon",
    ["Down ramp to Illhoof"] = "경사로 아래 Illhoof",
    ["Down ramp to Mol'dar"] = "경사로 아래 Mol'dar",
    ["Down ramp, go left"] = "경사로 아래, 왼쪽",
    ["Down spiral to Shad'har"] = "나선 아래 샤드하르",
    ["Down stairwell"] = "계단 아래로",
    ["Down to Cenarius"] = "아래 세나리우스",
    ["Down to Cho"] = "아래 초",
