    ["Drops from Druid of the Fang"] = "Druid of the Fang에게서 획득",
    ["During dance phase, run to the spotlight. Walk in the direction of the other NPCs a few times. Jump to clear debuff stacks."] = "춤 단계에서는 조명으로 달려가세요. 다른 NPC들이 움직이는 방향으로 몇 차례 걸으세요. 뛰어서 약화 효과 중첩을 제거하세요.",
    ["East exit to Flamelash"] = "동쪽 출구 Flamelash",
