    ["Enter Gates of Org"] = "오그리마 성문 진입",
    ["Enter Molten Crucible"] = "용암 도가니 진입",
    ["Enter the next room and kill ^Drest'agath^."] = "다음 방으로 들어가 ^Drest'agath^을 처치하세요.",
    ["Enter the room to engage with ^The Hivemind^."] = "방으로 들어가 ^The Hivemind^와 전투하세요.",
    ["Enter the water and click the ^Oxygen-Rich Membrane^ for swim speed and water breathing. You must kill the last trash pack in the tunnel to spawn ^Blackwater Behemoth^."] = "물에 들어가 ^Oxygen-Rich Membrane^을 클릭해 수영 속도와 수중 호흡 효과를 얻으세요. 터널의 마지막 일반 몬스터 무리를 처치해야 ^Blackwater Behemoth^가 생성됩니다.",
    ["Escort ^Muyoh^, stopping two times on the way to the final boss, ^Mutanus the Devourer^. Kill several waves of trash and the boss will spawn."] = "^Muyoh^를 호위하며 최종 우두머리 ^Mutanus the Devourer^에게 가는 길에 두 번 멈춥니다. 여러 일반 몬스터 무리를 처치하면 우두머리가 나타납니다.",
    ["Escort Muyoh to Mutanus"] = "Muyoh를 Mutanus까지 호위",
    ["Escort Muyoh"] = "Muyoh 호위",
    ["Essence of Eonar"] = "이오나의 정수",
    ["Essence Tokens"] = "정수 토큰",
    ["Exit and take second right"] = "나가서 두 번째 오른쪽",
    ["Exit building to south"] = "건물 남쪽으로 나가기",
    ["Exit east, then up the ramp"] = "동쪽으로 나간 뒤 경사로 위",
    ["Exit library then left"] = "도서관을 나가 왼쪽",
    ["Exit northeast to ramp"] = "북동쪽 출구, 경사로",
    ["Exit Portal Nearby"] = "근처 출구 차원문",
    ["Exit portal nearby."] = "근처에 출구 차원문이 있습니다.",
    ["Exit portal through north tunnel"] = "북쪽 터널의 출구 차원문",
