    ["Exit the ship"] = "함선에서 나오기",
    ["Exit the water, and walk back through the water channel until you reach ^Twilight Lord Bathiel^."] = "물에서 나와 물길을 되돌아가 ^Twilight Lord Bathiel^에게 가세요.",
    ["Exit tram to Mimiron"] = "전차에서 내려 미미론",
