    ["Left to Huntsman"] = "왼쪽 Huntsman",
    ["Left to kill Gatewatcher Gyro-Kill"] = "왼쪽: 문지기 회전톱날 처치",
    ["Left to Magister Kalendris"] = "왼쪽 Magister Kalendris",
    ["Left to Maut"] = "왼쪽 마우트",
    ["Left to Onyx Lab"] = "왼쪽 오닉스 연구실",
    ["Left to Quarry of Infusion"] = "왼쪽 주입의 채석장",
    ["Left to Scorched Hall"] = "왼쪽 그을린 전당",
    ["Left to The Elemental Conclave"] = "왼쪽 원소의 비밀의회",
    ["Left to Zakuun"] = "왼쪽 자쿠운",
    ["Legacy of Scholomance requires a one-time attunement that starts with {item}, dropped by ^Doctor Theolen Krastinov^, a Heroic-only rare that spawns after ^Rattlegore^ dies. After defeating ^Darkmaster Gandling^, use the toy on the pile of bones to summon ^Eva Sarkhoff^ and accept her quest. Once attuned, use {item2} at Caer Darrow to enter."] = "스칼로맨스의 유산은 한 번의 해금이 필요하며, {item}에서 시작합니다. 이 아이템은 ^Doctor Theolen Krastinov^가 드롭하며, 이 희귀 몬스터는 영웅 난이도에서만 ^Rattlegore^가 죽은 뒤 등장합니다. ^Darkmaster Gandling^을 처치한 뒤 뼈 더미에서 장난감을 사용해 ^Eva Sarkhoff^를 소환하고 퀘스트를 받으세요. 해금이 끝나면 Caer Darrow에서 {item2}를 사용해 입장하세요.",
    ["Legacy of Scholomance"] = "스칼로맨스의 유산",
    ["Legs"] = "다리",
    ["Library"] = "도서관",
    ["Light 2x Braziers with 2x Torches"] = "횃불 2개로 화로 2개 점화",
    ["Light Brazier (1)"] = "화로 점화 (1)",
    ["Light Brazier (2)"] = "화로 점화 (2)",
    ["Light's Breach Portal"] = "빛의 틈 차원문",
    ["Location: Butcher's Sanctum, past ^Rattlegore^"] = "위치: 도살자의 성소, ^Rattlegore^ 너머",
    ["Location: First level. Across the hall from ^Highlord Omokk^"] = "위치: 1층. ^Highlord Omokk^ 맞은편 복도",
    ["Long path east to Gizlock"] = "긴 동쪽 길 Gizlock",
    ["Long Path North"] = "북쪽 긴 길",
    ["Long path to Kalecgos"] = "Kalecgos까지 긴 길",
    ["Long upward path to Serpentis"] = "긴 오르막길 Serpentis",
    ["Loop around to Painsmith"] = "돌아가 고통장이",
    ["Loop north to Koranthal"] = "북쪽으로 돌아 Koranthal",
    ["Loop your way around the path and you will see ^Queen Azshara^ trapped. Clear the trash to engage ^Dark Inquisitor Xanesh^."] = "길을 따라 돌아가면 갇힌 ^Queen Azshara^를 볼 수 있습니다. 일반 몬스터를 처치해 ^Dark Inquisitor Xanesh^와 전투하세요.",
    ["Magma Orb"] = "용암 구슬",
    ["Make your way down the spiral, following the path to reach ^Shad'har the Insatiable^."] = "나선형 길을 내려가 ^Shad'har the Insatiable^에게 가세요.",
    ["Make your way up the path and stay to the right and find the map exit labeled ^The Ritual Chamber^."] = "길을 올라 오른쪽을 유지하며 지도에 ^The Ritual Chamber^로 표시된 출구를 찾으세요.",
    ["Malfurion then Iris"] = "말퓨리온 후 홍채",
    ["Malfurion"] = "말퓨리온",
    ["Moroes in Banquet Hall"] = "Banquet Hall의 Moroes",
    ["Motion Sick Peon"] = "Motion Sick Peon",
    ["Mount up and follow the path upstairs and across the bridge. Enter the building to the west."] = "탈것을 타고 길을 따라 계단을 올라 다리를 건너세요. 서쪽 건물로 들어가세요.",
    ["Mount up and ride north to the boss area. Clear trash until the boss spawns. Vehicles optional.\n\n|cffF259C7HARD MODE:|r Talk to ^Lore Keeper of Norgannon^ at the Expedition Camp to activate the towers, and leave them active during the boss fight."] = "탈것을 타고 북쪽의 우두머리 지역으로 가세요. 우두머리가 생성될 때까지 일반 몬스터를 처치하세요. 탈것 사용은 선택 사항입니다.\n\n|cffF259C7하드 모드:|r 원정대 야영지의 ^Lore Keeper of Norgannon^과 대화해 탑을 활성화하고, 우두머리 전투 중에도 활성 상태로 두세요.",
    ["Mulgore Portal"] = "멀고어 차원문",
    ["NE to Brackenspore"] = "북동쪽 담쟁이포자",
    ["Nethestrasz then Portal"] = "네테스트라즈 후 차원문",
    ["Next, continue west down the ramp to find ^Tendris Warpwood^."] = "다음으로 서쪽 경사로를 내려가 ^Tendris Warpwood^를 찾으세요.",
    ["Next, kill ^General Zarithrian^ to the south."] = "다음으로 남쪽의 ^General Zarithrian^을 처치하세요.",
    ["Next, kill ^Saviana Ragefire^ to the west."] = "다음으로 서쪽의 ^Saviana Ragefire^를 처치하세요.",
    ["No token vendor data available."] = "토큰 상인 데이터가 없습니다.",
    ["None available"] = "이용 가능한 방법 없음",
    ["North all the way to Kael"] = "끝까지 북쪽 Kael",
    ["North and west to Golemagg"] = "Golemagg까지 북쪽과 서쪽으로",
    ["North path to Cobrahn"] = "북쪽 길 Cobrahn",
    ["North path to Randolph"] = "북쪽 길 Randolph",
    ["North then east to Baroness"] = "북쪽 후 동쪽 Baroness",
